<?php
require_once __DIR__.'/../includes/bootstrap.php';
$user=require_login('provider');$bidId=(int)($_GET['bid_id']??0);
$stmt=db()->prepare("SELECT pb.*,tr.request_number,tr.destination,tr.start_date,tr.end_date FROM provider_bids pb JOIN providers p ON p.id=pb.provider_id JOIN trip_requests tr ON tr.id=pb.trip_request_id WHERE pb.id=? AND p.user_id=? LIMIT 1");$stmt->bind_param('ii',$bidId,$user['id']);$stmt->execute();$bid=$stmt->get_result()->fetch_assoc();if(!$bid){http_response_code(404);exit('Offer not found.');}
$stmt=db()->prepare('SELECT * FROM provider_bid_items WHERE bid_id=? ORDER BY id');$stmt->bind_param('i',$bidId);$stmt->execute();$items=$stmt->get_result();
$page_title='Offer Items';require __DIR__.'/../includes/header.php';
?><div class="container py-5" style="max-width:1000px"><div class="d-flex justify-content-between align-items-start mb-4"><div><h1 class="h3 mb-1">Build your offer</h1><p class="text-secondary mb-0"><?=e($bid['bid_number'])?> · <?=e($bid['request_number'])?> · <?=e($bid['destination'])?></p></div><a class="btn btn-outline-dark" href="/provider/request-view.php?id=<?=$bid['trip_request_id']?>">Back to request</a></div><?php if($msg=flash('success')):?><div class="alert alert-success"><?=e($msg)?></div><?php endif;?><?php if($msg=flash('error')):?><div class="alert alert-danger"><?=e($msg)?></div><?php endif;?><form method="post" action="/provider/bid-item-save.php" id="offerForm"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="bid_id" value="<?=$bidId?>"><div id="items"><?php $n=0;while($item=$items->fetch_assoc()):$n++;?><div class="card p-3 mb-3 item-row"><div class="row g-2"><div class="col-md-2"><label class="form-label">Type</label><select name="item_type[]" class="form-select"><option value="hotel" <?=$item['item_type']==='hotel'?'selected':''?>>Hotel</option><option value="transfer" <?=$item['item_type']==='transfer'?'selected':''?>>Transfer</option><option value="activity" <?=$item['item_type']==='activity'?'selected':''?>>Activity</option><option value="guide" <?=$item['item_type']==='guide'?'selected':''?>>Guide</option><option value="flight" <?=$item['item_type']==='flight'?'selected':''?>>Flight</option><option value="other" <?=$item['item_type']==='other'?'selected':''?>>Other</option></select></div><div class="col-md-4"><label class="form-label">Item</label><input name="title[]" class="form-control" value="<?=e($item['title'])?>" required></div><div class="col-md-2"><label class="form-label">Qty</label><input name="quantity[]" class="form-control qty" type="number" min="0.01" step="0.01" value="<?=e((string)$item['quantity'])?>" required></div><div class="col-md-2"><label class="form-label">Unit price</label><input name="unit_price[]" class="form-control price-input" type="number" min="0" step="0.01" value="<?=e((string)$item['unit_price'])?>" required></div><div class="col-md-2"><label class="form-label">Line total</label><input class="form-control line-total" readonly value="<?=number_format((float)$item['total_price'],2,'.','')?>"><button type="button" class="btn btn-link text-danger px-0 remove-item">Remove</button></div><div class="col-12"><textarea name="item_description[]" class="form-control" rows="2" placeholder="Inclusions, room type, transfer details, cancellation terms..."><?=e($item['description']??'')?></textarea></div></div></div><?php endwhile;if($n===0):?><div class="card p-3 mb-3 item-row"><div class="row g-2"><div class="col-md-2"><label class="form-label">Type</label><select name="item_type[]" class="form-select"><option value="hotel">Hotel</option><option value="transfer">Transfer</option><option value="activity">Activity</option><option value="guide">Guide</option><option value="flight">Flight</option><option value="other">Other</option></select></div><div class="col-md-4"><label class="form-label">Item</label><input name="title[]" class="form-control" required></div><div class="col-md-2"><label class="form-label">Qty</label><input name="quantity[]" class="form-control qty" type="number" min="0.01" step="0.01" value="1" required></div><div class="col-md-2"><label class="form-label">Unit price</label><input name="unit_price[]" class="form-control price-input" type="number" min="0" step="0.01" value="0" required></div><div class="col-md-2"><label class="form-label">Line total</label><input class="form-control line-total" readonly value="0.00"><button type="button" class="btn btn-link text-danger px-0 remove-item">Remove</button></div><div class="col-12"><textarea name="item_description[]" class="form-control" rows="2" placeholder="Inclusions, room type, transfer details, cancellation terms..."></textarea></div></div></div><?php endif;?></div><button type="button" class="btn btn-outline-secondary" id="addItem">+ Add item</button><div class="card mt-4 p-4"><div class="d-flex justify-content-between align-items-center"><span class="h5 mb-0">Calculated offer total</span><strong class="h3 mb-0">₹<span id="grandTotal">0.00</span></strong></div><small class="text-secondary">The server recalculates this total from the submitted line items.</small></div><button class="btn btn-dark mt-4">Save offer &amp; total</button></form></div><script>function recalc(){let total=0;document.querySelectorAll('.item-row').forEach(r=>{let q=parseFloat(r.querySelector('.qty')?.value||0),p=parseFloat(r.querySelector('.price-input')?.value||0),t=Math.round(q*p*100)/100;if(r.querySelector('.line-total'))r.querySelector('.line-total').value=t.toFixed(2);total+=t;});document.getElementById('grandTotal').textContent=total.toFixed(2)}function wire(){document.querySelectorAll('.qty,.price-input').forEach(x=>x.addEventListener('input',recalc));document.querySelectorAll('.remove-item').forEach(x=>x.onclick=()=>{if(document.querySelectorAll('.item-row').length>1){x.closest('.item-row').remove();recalc();}})}document.getElementById('addItem').onclick=()=>{let src=document.querySelector('.item-row');let clone=src.cloneNode(true);clone.querySelectorAll('input,textarea').forEach(x=>{if(x.classList.contains('qty'))x.value='1';else if(x.classList.contains('price-input'))x.value='0';else if(x.classList.contains('line-total'))x.value='0.00';else x.value='';});document.getElementById('items').appendChild(clone);wire();recalc()};wire();recalc();</script><?php require __DIR__.'/../includes/footer.php'; ?>
